&lt;p&gt;&lt;strong&gt;Arrested:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;Evan&amp;nbsp;Matthew&amp;nbsp;Hiatt, 20-year-old Bend resident&lt;/span&gt;&lt;span style="font-family:wordvisicarriagereturn_msfontservice,calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;br /&gt;
&lt;strong&gt;Offenses:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;Encouraging Child Sex Abuse I x10, Encouraging Child Sex Abuse II x10&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW91498427 BCX0" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;strong&gt;Arrested:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;Mitchel&amp;nbsp;Joseph&amp;nbsp;Gregg, 23-year-old Bend resident&lt;/span&gt;&lt;span style="font-family:wordvisicarriagereturn_msfontservice,calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;br /&gt;
&lt;strong&gt;Offenses:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;Encouraging Child Sex Abuse I, Encouraging Child Sex Abuse II&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

