&lt;div class="OutlineElement Ltr SCXW65526603 BCX0" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;strong&gt;Arrested:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;Katen Von Blalack, 39-year-old Redmond resident&lt;/span&gt;&lt;span style="font-family:wordvisicarriagereturn_msfontservice,calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;br /&gt;
&lt;strong&gt;Offenses:&amp;nbsp;&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;Unlawful Delivery of Fentanyl&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif; font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
