round-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;ffice, and the Crook County Sheriff&rsquo;s&amp;nbsp;&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;O&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;ffice&amp;nbsp;&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;for&amp;nbsp;&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;their&amp;nbsp;&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;ass&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;istance&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;&amp;nbsp;in&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;&amp;nbsp;the investigation&amp;nbsp;&lt;/span&gt;&lt;span style="background-color:rgb(255, 255, 255); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:14.6667px"&gt;over the past few days.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
